<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Country</title><link rel='stylesheet' href='/assets/css/ui.css'><link rel='stylesheet' href='/assets/css/components.css'><link rel='stylesheet' href='https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css'></head><body><script src='/assets/js/ui.js'></script><script>
UX.shell('',`<div id='wrap' class='glass-card'><div class='skeleton' style='height:120px'></div></div>`);
(async()=>{const id=Number(location.pathname.split('/').pop()||0);try{const c=await UX.api('/api/map/country-detail?id='+id);wrap.innerHTML=`<div class='hero'><h2>${c.country_name||c.name}</h2><span class='badge'>${c.government_type||''}</span></div><div class='grid cols-3'><div class='glass-card'><div class='sub'>Total Regions</div><div class='kpi'>${UX.fmt(c.region_count)}</div></div><div class='glass-card'><div class='sub'>Treasury</div><div class='kpi'>${UX.fmt(c.treasury_state_money)}</div></div><div class='glass-card'><div class='sub'>Gold</div><div class='kpi'>${UX.fmt(c.treasury_gold)}</div></div></div><h3>Regions</h3><div class='list'>${(c.regions||[]).map(r=>`<a class='row' href='/region/${r.id}'><span>${r.name}</span><small class='sub'>${r.region_type}</small></a>`).join('')}</div>`;}catch(e){wrap.innerHTML=e.message;}})();
</script></body></html>
